1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    font: 16px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
12	    background: #f5f5f4;
13	    color: #1c1917;
14	  }
15	  main {
16	    max-width: 32rem;
17	    margin: 3rem auto;
18	    padding: 0 1rem;
19	  }
20	  h1 { font-size: 1.5rem; margin: 0 0 1rem; }
21	  form { display: flex; flex-wrap: wrap; gap: 0.5rem; }
22	  input[type="text"] { flex: 1 1 8rem; }
23	  input[type="text"], input[type="date"], select {
24	    min-width: 0;
25	    padding: 0.6rem 0.75rem;
26	    font: inherit;
27	    border: 1px solid #d6d3d1;
28	    border-radius: 6px;
29	    background: #fff;
30	  }
31	  input[type="date"], select { color: #57534e; }
32	  input[type="text"]:focus, input[type="date"]:focus, select:focus { outline: 2px solid #2563eb; outline-offset: -1px; border-color: transparent; }
33	  button {
34	    font: inherit;
35	    padding: 0.6rem 1rem;
36	    border: 0;
37	    border-radius: 6px;
38	    cursor: pointer;
39	  }
40	  .add { background: #2563eb; color: #fff; }
41	  .add:hover { background: #1d4ed8; }
42	  ul { list-style: none; margin: 1.25rem 0 0; padding: 0; }
43	  li {
44	    display: flex;
45	    align-items: center;
46	    gap: 0.75rem;
47	    padding: 0.6rem 0.75rem;
48	    background: #fff;
49	    border: 1px solid #e7e5e4;
50	    border-radius: 6px;
51	    margin-bottom: 0.5rem;
52	  }
53	  .text { flex: 1; overflow-wrap: anywhere; }
54	  .delete { background: transparent; color: #b91c1c; padding: 0.3rem 0.6rem; }
55	  .delete:hover { background: #fee2e2; }
56	  .empty { color: #78716c; margin-top: 1.25rem; }
57	  .filters { display: flex; gap: 0.25rem; margin-top: 1rem; }
58	  .filters button { background: transparent; color: #57534e; padding: 0.3rem 0.75rem; }
59	  .filters button:hover { background: #e7e5e4; }
60	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; }
61	  .toggle { width: 1.1rem; height: 1.1rem; margin: 0; flex: none; cursor: pointer; accent-color: #2563eb; }
62	  li[data-completed="true"] .text { color: #a8a29e; text-decoration: line-through; }
63	  .due { flex: none; font-size: 0.85rem; color: #78716c; white-space: nowrap; }
64	  /* Priority is a neutral text label; colour is reserved for the overdue highlight. */
65	  .priority { flex: none; font-size: 0.75rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.03em; padding: 0.1rem 0.4rem; border-radius: 4px; color: #57534e; background: #f5f5f4; }
66	  li[data-overdue="true"] { border-color: #f87171; }
67	  li[data-overdue="true"] .due { color: #b91c1c; font-weight: 600; }
68	</style>
69	</head>
70	<body>
71	<main>
72	  <h1>Todos</h1>
73	  <form id="todo-form" autocomplete="off">
74	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo">
75	    <input data-testid="todo-due" type="date" aria-label="Due date (optional)">
76	    <select data-testid="todo-priority" aria-label="Priority">
77	      <option value="low">Low</option>
78	      <option value="med" selected>Med</option>
79	      <option value="high">High</option>
80	    </select>
81	    <button data-testid="todo-add" class="add" type="submit">Add</button>
82	  </form>
83	  <div class="filters" role="group" aria-label="Filter todos">
84	    <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
85	    <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
86	    <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
87	  </div>
88	  <ul data-testid="todo-list"></ul>
89	  <p class="empty" hidden>No todos yet.</p>
90	</main>
91	<script>
92	(function () {
93	  var STORAGE_KEY = 'todos';
94	  var form = document.getElementById('todo-form');
95	  var input = document.querySelector('[data-testid="todo-input"]');
96	  var dueInput = document.querySelector('[data-testid="todo-due"]');
97	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
98	  var list = document.querySelector('[data-testid="todo-list"]');
99	  var empty = document.querySelector('.empty');
100	  var filterButtons = document.querySelectorAll('[data-filter]');
101	  var filter = 'all';
102	
103	  function load() {
104	    try {
105	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
106	      if (!Array.isArray(data)) return [];
107	      return data.filter(function (t) {
108	        return t && typeof t.id === 'string' && typeof t.text === 'string';
109	      }).map(function (t) {
110	        t.completed = t.completed === true;
111	        t.due = isDateString(t.due) ? t.due : null;
112	        t.priority = isPriority(t.priority) ? t.priority : DEFAULT_PRIORITY;
113	        return t;
114	      });
115	    } catch (e) {
116	      return [];
117	    }
118	  }
119	
120	  function save() {
121	    try {
122	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
123	    } catch (e) {
124	      // Storage unavailable or full; keep working in memory.
125	    }
126	  }
127	
128	  var PRIORITIES = ['low', 'med', 'high'];
129	  var DEFAULT_PRIORITY = 'med';
130	  var PRIORITY_LABELS = { low: 'Low', med: 'Med', high: 'High' };
131	
132	  function isPriority(value) {
133	    return PRIORITIES.indexOf(value) !== -1;
134	  }
135	
136	  function makeId() {
137	    if (window.crypto && typeof crypto.randomUUID === 'function') {
138	      try { return crypto.randomUUID(); } catch (e) { /* fall through */ }
139	    }
140	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
141	  }
142	
143	  // Due date rule (project decision): `due` is a plain 'YYYY-MM-DD' string
144	  // holding a LOCAL calendar date, or null. Never parse it with `new Date(str)`
145	  // (that reads it as UTC midnight). Overdue means due < today's local date,
146	  // compared as strings; a todo due today is never overdue.
147	  function isDateString(value) {
148	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value);
149	  }
150	
151	  function pad(n) {
152	    return (n < 10 ? '0' : '') + n;
153	  }
154	
155	  function todayLocal() {
156	    var d = new Date();
157	    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
158	  }
159	
160	  function isOverdue(todo, today) {
161	    return todo.due !== null && todo.due < today;
162	  }
163	
164	  function formatDue(due) {
165	    var parts = due.split('-');
166	    var local = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
167	    return local.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
168	  }
169	
170	  // Ordering rule (project decision): completed todos always sit below all
171	  // active todos. Within each group, higher priority comes first
172	  // (high, med, low); equal priority keeps insertion order, oldest first.
173	  // `todos` is stored in insertion order and never reordered.
174	  var PRIORITY_RANK = { high: 0, med: 1, low: 2 };
175	
176	  function ordered() {
177	    return todos.map(function (t, i) { return { todo: t, index: i }; })
178	      .sort(function (a, b) {
179	        return (a.todo.completed - b.todo.completed) ||
180	          (PRIORITY_RANK[a.todo.priority] - PRIORITY_RANK[b.todo.priority]) ||
181	          (a.index - b.index);
182	      })
183	      .map(function (entry) { return entry.todo; });
184	  }
185	
186	  function visible(todo) {
187	    if (filter === 'active') return !todo.completed;
188	    if (filter === 'completed') return todo.completed;
189	    return true;
190	  }
191	
192	  function render() {
193	    list.textContent = '';
194	    var shown = ordered().filter(visible);
195	    var today = todayLocal();
196	    renderedDay = today;
197	    shown.forEach(function (todo) {
198	      var li = document.createElement('li');
199	      li.setAttribute('data-testid', 'todo-item');
200	      li.setAttribute('data-id', todo.id);
201	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
202	      li.setAttribute('data-priority', todo.priority);
203	      li.setAttribute('data-overdue', isOverdue(todo, today) ? 'true' : 'false');
204	
205	      var box = document.createElement('input');
206	      box.type = 'checkbox';
207	      box.className = 'toggle';
208	      box.setAttribute('data-testid', 'todo-toggle');
209	      box.setAttribute('aria-label', 'Mark "' + todo.text + '" complete');
210	      box.checked = todo.completed;
211	      box.addEventListener('change', function () { toggle(todo.id); });
212	
213	      var span = document.createElement('span');
214	      span.className = 'text';
215	      span.setAttribute('data-testid', 'todo-text');
216	      span.textContent = todo.text;
217	
218	      var del = document.createElement('button');
219	      del.type = 'button';
220	      del.className = 'delete';
221	      del.setAttribute('data-testid', 'todo-delete');
222	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
223	      del.textContent = 'Delete';
224	      del.addEventListener('click', function () { remove(todo.id); });
225	
226	      li.appendChild(box);
227	      var priority = document.createElement('span');
228	      priority.className = 'priority';
229	      priority.textContent = PRIORITY_LABELS[todo.priority];
230	
231	      li.appendChild(span);
232	      li.appendChild(priority);
233	      if (todo.due) {
234	        var due = document.createElement('time');
235	        due.className = 'due';
236	        due.setAttribute('data-testid', 'todo-due-date');
237	        due.setAttribute('datetime', todo.due);
238	        due.textContent = (isOverdue(todo, today) ? 'Overdue: ' : 'Due ') + formatDue(todo.due);
239	        li.appendChild(due);
240	      }
241	      li.appendChild(del);
242	      list.appendChild(li);
243	    });
244	    if (todos.length === 0) {
245	      empty.textContent = 'No todos yet.';
246	    } else if (filter === 'active') {
247	      empty.textContent = 'No active todos.';
248	    } else {
249	      empty.textContent = 'No completed todos.';
250	    }
251	    empty.hidden = shown.length > 0;
252	
253	    filterButtons.forEach(function (btn) {
254	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
255	    });
256	  }
257	
258	  function add(text, due, priority) {
259	    text = text.trim();
260	    if (!text) return false;
261	    todos.push({
262	      id: makeId(),
263	      text: text,
264	      completed: false,
265	      due: isDateString(due) ? due : null,
266	      priority: isPriority(priority) ? priority : DEFAULT_PRIORITY,
267	      createdAt: Date.now()
268	    });
269	    save();
270	    render();
271	    return true;
272	  }
273	
274	  function remove(id) {
275	    todos = todos.filter(function (t) { return t.id !== id; });
276	    save();
277	    render();
278	  }
279	
280	  function toggle(id) {
281	    todos.forEach(function (t) {
282	      if (t.id === id) t.completed = !t.completed;
283	    });
284	    save();
285	    render();
286	  }
287	
288	  var todos = load();
289	  var renderedDay = null;
290	
291	  // Re-render when the local date rolls over so overdue flags stay current.
292	  function refreshIfNewDay() {
293	    if (todayLocal() !== renderedDay) render();
294	  }
295	  setInterval(refreshIfNewDay, 60 * 1000);
296	  document.addEventListener('visibilitychange', function () {
297	    if (!document.hidden) refreshIfNewDay();
298	  });
299	
300	  filterButtons.forEach(function (btn) {
301	    btn.addEventListener('click', function () {
302	      filter = btn.getAttribute('data-filter');
303	      render();
304	    });
305	  });
306	
307	  form.addEventListener('submit', function (e) {
308	    e.preventDefault();
309	    if (add(input.value, dueInput.value, priorityInput.value)) {
310	      dueInput.value = '';
311	      priorityInput.value = DEFAULT_PRIORITY;
312	    }
313	    input.value = '';
314	    input.focus();
315	  });
316	
317	  render();
318	})();
319	</script>
320	</body>
321	</html>
