const { chromium } = require('playwright');
const assert = require('assert');
(async () => {
  const b = await chromium.launch(); const p = await b.newPage();
  const errs = []; p.on('pageerror', e => errs.push(e.message));
  await p.goto('file:///Users/vmysla/src/product-tracebility-ab-testing/ab-study/arms/todo-rep-control-03/control/index.html');
  const texts = () => p.$$eval('[data-testid="todo-text"]', els => els.map(e => e.textContent));
  for (const t of ['Buy milk', 'Walk dog', 'buy BREAD']) { await p.fill('[data-testid="todo-input"]', t); await p.press('[data-testid="todo-input"]', 'Enter'); }
  // Enter commits
  await p.dblclick('text=Walk dog');
  await p.fill('[data-testid="todo-edit-input"]', 'Walk cat');
  await p.press('[data-testid="todo-edit-input"]', 'Enter');
  assert.deepStrictEqual(await texts(), ['Buy milk', 'Walk cat', 'buy BREAD']);
  // Escape cancels
  await p.dblclick('text=Walk cat');
  await p.fill('[data-testid="todo-edit-input"]', 'nope');
  await p.press('[data-testid="todo-edit-input"]', 'Escape');
  assert.deepStrictEqual(await texts(), ['Buy milk', 'Walk cat', 'buy BREAD']);
  // Blur commits, and the click that blurred still lands
  await p.dblclick('text=Buy milk');
  await p.fill('[data-testid="todo-edit-input"]', 'Buy oat milk');
  await p.locator('[data-testid="todo-toggle"]').nth(2).click();
  assert.deepStrictEqual(await texts(), ['Buy oat milk', 'Walk cat', 'buy BREAD']);
  assert.strictEqual(await p.locator('[data-testid="todo-item"][data-completed="true"]').count(), 1);
  // Persisted
  await p.reload();
  assert.deepStrictEqual(await texts(), ['Buy oat milk', 'Walk cat', 'buy BREAD']);
  // Search, case-insensitive
  await p.fill('[data-testid="search-input"]', 'BUY');
  assert.deepStrictEqual(await texts(), ['Buy oat milk', 'buy BREAD']);
  // Combined with Active
  await p.click('[data-testid="filter-active"]');
  assert.deepStrictEqual(await texts(), ['Buy oat milk']);
  await p.click('[data-testid="filter-completed"]');
  assert.deepStrictEqual(await texts(), ['buy BREAD']);
  await p.fill('[data-testid="search-input"]', 'zzz');
  assert.strictEqual(await p.textContent('.empty'), 'No todos match your search.');
  await p.fill('[data-testid="search-input"]', '');
  await p.click('[data-testid="filter-all"]');
  assert.strictEqual((await texts()).length, 3);
  // Edit under search so it no longer matches -> hidden
  await p.fill('[data-testid="search-input"]', 'walk');
  await p.dblclick('text=Walk cat');
  await p.fill('[data-testid="todo-edit-input"]', 'Feed cat');
  await p.press('[data-testid="todo-edit-input"]', 'Enter');
  assert.deepStrictEqual(await texts(), []);
  assert.deepStrictEqual(errs, []);
  console.log('ok'); await b.close();
})().catch(e => { console.error(e); process.exit(1); });
